function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 20000) return 'nums needs 1 to 20000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each value is an integer from 1 to 100000.';
  if (new Set(nums).size !== nums.length) return 'The values must be distinct.';
  return null;
}

