function largestComponentSize(nums) {
  const parent = nums.map((_, i) => i);
  const size = new Array(nums.length).fill(1);
  const owner = new Map();
  let best = 1;

  function find(x) {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  }

  function join(i, prime) {
    if (!owner.has(prime)) {
      owner.set(prime, i);
      return;
    }
    let a = find(i);
    let b = find(owner.get(prime));
    if (a === b) {
      return;
    }
    if (size[a] < size[b]) {
      [a, b] = [b, a];
    }
    parent[b] = a;
    size[a] += size[b];
    best = Math.max(best, size[a]);
  }

  for (let i = 0; i < nums.length; i++) {
    let value = nums[i];
    for (let p = 2; p * p <= value; p++) {
      if (value % p !== 0) {
        continue;
      }
      join(i, p);
      while (value % p === 0) {
        value /= p;
      }
    }
    if (value > 1) {
      join(i, value);
    }
  }
  return best;
}

