function largestComponentSize(nums) {
  // Test every pair with gcd, then measure each component with a depth-first search.
  const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));
  const n = nums.length;
  const seen = new Array(n).fill(false);
  let largest = 0;
  for (let s = 0; s < n; s++) {
    if (seen[s]) continue;
    seen[s] = true;
    const stack = [s];
    let count = 0;
    while (stack.length) {
      const u = stack.pop();
      count++;
      for (let v = 0; v < n; v++) {
        if (!seen[v] && gcd(nums[u], nums[v]) > 1) { seen[v] = true; stack.push(v); }
      }
    }
    largest = Math.max(largest, count);
  }
  return largest;
}

