function generate(rand, size) {
  const pickDistinct = (count, choose) => {
    const chosen = new Set();
    while (chosen.size < count) chosen.add(choose());
    return [...chosen];
  };
  if (size === 'small') {
    const top = rand() < 0.5 ? 20 : 60;
    const count = 1 + Math.floor(rand() * Math.min(10, top));
    return [pickDistinct(count, () => 1 + Math.floor(rand() * top))];
  }
  const count = 2000;
  if (rand() < 0.5) return [pickDistinct(count, () => 1 + Math.floor(rand() * 100000))];
  // Mostly primes, plus a few of their multiples, so the graph splits into many components.
  const composite = new Uint8Array(100001);
  const primes = [];
  for (let p = 2; p <= 100000; p++) {
    if (composite[p]) continue;
    primes.push(p);
    for (let q = p * p; q <= 100000; q += p) composite[q] = 1;
  }
  return [pickDistinct(count, () => {
    const prime = primes[Math.floor(rand() * primes.length)];
    if (rand() < 0.8) return prime;
    const factor = 2 + Math.floor(rand() * Math.max(1, Math.floor(100000 / prime) - 1));
    return prime * factor <= 100000 ? prime * factor : prime;
  })];
}
